{
  "items": [
    {
      "title": "Linked Personnel Panel (LPP) – Quality of Work and Economic Success in Germany (2012–2017)",
      "url_or_doi": "https://doi.org/10.5164/IAB.LPP1617.de.en.v1",
      "justification": "One of the most relevant datasets for studying employee job performance in Germany during the 2010s. The Linked Personnel Panel combines employee surveys with employer-level information from German establishments. Survey waves conducted in 2012/2013, 2014/2015, and 2016/2017 cover more than 7,000 employees and approximately 700–1,200 establishments per wave. Variables include performance appraisals, performance-related bonuses, employee motivation, job satisfaction, working conditions, management practices, and organizational performance. Particularly suitable for longitudinal research examining factors associated with individual job performance."
    },
    {
      "title": "Linked Personnel Panel (LPP) – First Wave (2012/2013)",
      "url_or_doi": "https://fdz.iab.de/en/publication/?id=5036284",
      "justification": "A German employer-employee dataset containing information from 1,219 establishments and 7,508 employees. It includes measures of employee performance evaluation, performance-related compensation, professional development, working conditions, and human resource management. The employer survey records the use of performance appraisal systems, while the employee survey includes information about performance-related bonuses and promotion criteria. Especially useful for examining the relationship between organizational practices and employee performance in Germany in the early 2010s. The linked page provides official documentation; access to the underlying microdata is restricted."
    },
    {
      "title": "Linked Personnel Panel (LPP) – Version 1221",
      "url_or_doi": "https://fdz.iab.de/en/int_bd_pd/linked-personnel-panel-lpp-version-1221-v1-2/",
      "justification": "An expanded longitudinal employer-employee dataset maintained by Germany's Institute for Employment Research (IAB). It includes survey waves spanning the 2010s and later years, allowing researchers to isolate observations from 2012 through 2019. Variables cover individual job quality, employee attitudes, human resource management, and firm performance. Particularly valuable for investigating how management practices, working conditions, and employee characteristics relate to organizational outcomes over time. Access is available through the IAB Research Data Centre under controlled conditions."
    },
    {
      "title": "BIBB/BAuA Employment Survey 2018 – Work and Occupation in Transition",
      "url_or_doi": "https://doi.org/10.4232/1.13433",
      "justification": "A nationally representative survey of approximately 20,000 employed individuals in Germany, conducted by the Federal Institute for Vocational Education and Training (BIBB) and the Federal Institute for Occupational Safety and Health (BAuA). It provides detailed information about job requirements, occupational tasks, qualifications, skills utilization, working conditions, and occupational demands. Although it does not primarily measure supervisor-rated individual performance, it is useful for studying factors associated with employee productivity, work effectiveness, and occupational outcomes in Germany during 2018."
    },
    {
      "title": "BIBB/BAuA Employment Surveys 2012 and 2018",
      "url_or_doi": "https://www.bibb.de/en/15182.php",
      "justification": "A collection of nationally representative German employment surveys with approximately 20,000 respondents per wave. The 2012 and 2018 surveys provide comparable information about occupational characteristics, job requirements, working conditions, professional qualifications, training, and skills utilization. These measures can support research on determinants and indirect indicators of job performance, including employee competencies and job demands. The availability of harmonized data makes the surveys especially useful for examining changes in working conditions and performance-related factors throughout the 2010s."
    },
    {
      "title": "GESIS Online Panel Pilot – Education and Employment (2011–2012)",
      "url_or_doi": "https://datacatalogue.cessda.eu/detail/8c3547501d2ad4f363a8a3f83dd7698040ab703c17ab4446d414fb2ea5c05a32?lang=en",
      "justification": "A German survey dataset collected between April 2011 and February 2012 covering employment, occupational characteristics, work motivation, job commitment, and perceptions of career success. It includes measures relevant to understanding employee engagement and work-related attitudes, which can be investigated as potential correlates of job performance. Particularly suitable for research focusing on psychological and motivational aspects of employment in Germany during the early 2010s. It is less suitable for directly measuring objective employee performance."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Work Orientations IV (2015)",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/browse",
      "justification": "The ISSP Work Orientations IV survey, conducted in 2015, includes Germany among its participating countries. It examines attitudes toward work, job satisfaction, employment relationships, occupational preferences, and perceptions of working conditions. These variables are useful for investigating motivational and organizational factors potentially associated with job performance. The international design also allows comparisons between German employees and workers in other countries. The linked GESIS data catalogue provides a starting point for locating the survey. The dataset primarily measures work attitudes rather than directly observed individual performance."
    }
  ]
}
